      --line: #e1e7ef;
      --accent: #3459c8;
      --p50: #9eb4f5;
      --slow: #a4421e;
      --slow-bar: #d26c37;
      --lobe-color-primary: #3459c8;
      font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--ink);
      background: var(--canvas);
    }
    * { box-sizing: border-box; }
    body { margin: 0; }
    .top { background: var(--surface); border-bottom: 1px solid var(--line); }
    .top-inner, main { width: min(1184px, calc(100% - 64px)); margin-inline: auto; }
    .top-inner { min-height: 62px; display: flex; align-items: center; justify-content: space-between; gap: 16px; }
    .brand { display: flex; align-items: center; gap: 10px; font-weight: 700; font-size: 14px; }
    .brand-icon {
      display: grid;
      place-items: center;
      inline-size: 31px;
      block-size: 31px;
      color: white;
      background: var(--accent);
      border-radius: 8px;
    }
    main { padding-block: 38px 48px; }
    .intro { margin-bottom: 25px; }
    h1, h2, p { margin: 0; }
    h1 { font-size: clamp(29px, 4vw, 42px); line-height: 1.12; letter-spacing: -.045em; }
    .intro p, .panel-meta p { color: var(--muted); font-size: 14px; line-height: 1.5; }
    .intro p { margin-top: 8px; }
    .summary { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px; margin-bottom: 20px; }
    .summary ryugi-card { min-width: 0; display: block; }
    .metric { display: flex; justify-content: space-between; align-items: flex-start; gap: 8px; padding: 2px; }
    .metric-label { font-size: 13px; color: var(--muted); font-weight: 600; }
    .metric-value { display: block; font-size: 30px; font-weight: 720; letter-spacing: -.045em; margin-top: 4px; font-variant-numeric: tabular-nums; }
    .metric-detail { font-size: 12px; color: var(--muted); margin-top: 4px; }
    .metric-icon { color: var(--accent); margin-top: 2px; }
    .metric-icon.warn, #slow-count { color: var(--slow); }
    .panel { display: block; }
    .panel-meta { display: flex; align-items: center; justify-content: space-between; gap: 12px 24px; flex-wrap: wrap; padding: 2px 2px 17px; }
    h2 { font-size: 20px; letter-spacing: -.025em; margin-bottom: 3px; }
    .legend { display: flex; flex-wrap: wrap; gap: 14px; font-size: 12px; color: var(--muted); }
    .legend span { display: inline-flex; align-items: center; gap: 6px; }
    .legend i { width: 13px; height: 5px; border-radius: 3px; background: var(--swatch); }
    .controls {
      display: grid;
      grid-template-columns: minmax(150px, 1.2fr) minmax(108px, .55fr) minmax(145px, .72fr) minmax(180px, 1.15fr);
      gap: 14px;
      padding: 15px 12px;
      background: #f5f7fb;
      border-block: 1px solid var(--line);
    }
    .field { min-width: 0; display: grid; gap: 6px; align-content: start; }
    .field > span { font-size: 12px; font-weight: 650; }
    .field > :last-child { display: block; width: 100%; }
    .table-wrap { overflow-x: auto; }
    table { border-collapse: collapse; width: 100%; min-width: 650px; table-layout: fixed; font-size: 13px; }
    th, td { padding: 11px 9px; border-bottom: 1px solid var(--line); text-align: left; }
    thead th { font-size: 11px; color: var(--muted); font-weight: 700; padding-block: 13px; }
    thead th[aria-sort] { color: var(--accent); }
    tbody tr:last-child > * { border-bottom: 0; }
    tbody tr.slow { background: #fff5ee; }
    tbody tr:hover { background: #f2f5ff; }
    tbody tr.slow:hover { background: #ffeee3; }
    .method-col { width: 86px; }
    .number-col { width: 75px; }
    .chart-col { width: 27%; }
    .status-col { width: 85px; }
    .path-cell { overflow-wrap: anywhere; font-weight: 500; }
    .path-cell code { font: 12px ui-monospace, "SFMono-Regular", Consolas, monospace; }
    .numeric { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
    tbody .p95 { font-weight: 700; }
    .slow .p95 { color: var(--slow); }
    .chart { position: relative; margin-inline: 10px 4px; height: 17px; background: #edf1f7; border-radius: 3px; overflow: hidden; }
    .bar { position: absolute; left: 0; height: 4px; border-radius: 2px; }
    .bar-50 { top: 3px; background: var(--p50); }
    .bar-95 { bottom: 3px; background: var(--accent); }
    .slow .bar-95 { background: var(--slow-bar); }
    .threshold-line { position: absolute; inset-block: 0; width: 1px; background: #66748a; }
    .scale { display: flex; justify-content: space-between; margin-inline: 10px 4px; font-variant-numeric: tabular-nums; }
    .scale span:first-child { color: var(--muted); }
    .status-ok { color: var(--muted); }
    .empty { padding: 32px 12px; color: var(--muted); text-align: center; }
    .foot { padding: 13px 2px 1px; border-top: 1px solid var(--line); color: var(--muted); font-size: 12px; line-height: 1.5; }
    .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
    @media (max-width: 800px) {
      .top-inner, main { width: calc(100% - 36px); }
      .controls { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    }
    @media (max-width: 465px) {
      main { padding-top: 25px; }
      .summary { gap: 8px; }
      .metric { padding: 0; }
      .metric-icon { display: none; }
      .metric-value { font-size: 24px; }
      .controls { grid-template-columns: minmax(0, 1fr); }
    }
  </style>
</head>
<body>
  <header class="top">
    <div class="top-inner">
      <div class="brand">
        <span class="brand-icon"><ryugi-icon name="activity" size="17" aria-hidden="true"></ryugi-icon></span>
        API Observability
      </div>
      <ryugi-tag size="small" variant="outlined">Sample data · 24 hours</ryugi-tag>
    </div>
  </header>
  <main>
    <div class="intro">
      <h1>Latency Explorer</h1>
      <p>Compare median and tail response times across 24 API endpoints.</p>
    </div>

    <section class="summary" aria-label="Latency summary">
      <ryugi-card variant="outlined">
        <div class="metric">
          <div><div class="metric-label">Endpoints shown</div><output class="metric-value" id="endpoint-count">24</output><div class="metric-detail">of 24 total</div></div>
          <ryugi-icon class="metric-icon" name="layers" size="17" aria-hidden="true"></ryugi-icon>
        </div>
      </ryugi-card>
      <ryugi-card variant="outlined">
        <div class="metric">
          <div><div class="metric-label">Slow endpoints</div><output class="metric-value" id="slow-count">8</output><div class="metric-detail" id="slow-detail">p95 above 450 ms</div></div>
          <ryugi-icon class="metric-icon warn" name="clock" size="17" aria-hidden="true"></ryugi-icon>
        </div>
      </ryugi-card>
      <ryugi-card variant="outlined">
        <div class="metric">
          <div><div class="metric-label">Highest p95</div><output class="metric-value" id="highest">986 ms</output><div class="metric-detail">among shown endpoints</div></div>
          <ryugi-icon class="metric-icon" name="arrow-up-right" size="17" aria-hidden="true"></ryugi-icon>
        </div>
      </ryugi-card>
    </section>

    <ryugi-card class="panel" variant="outlined">
      <div class="panel-meta">
        <div><h2 id="endpoints-title">Endpoint latency</h2><p id="result-count" aria-live="polite">Showing all 24 endpoints</p></div>
        <div class="legend" aria-label="Latency chart legend">
          <span><i style="--swatch: var(--p50)" aria-hidden="true"></i>p50</span>
          <span><i style="--swatch: var(--accent)" aria-hidden="true"></i>p95</span>
          <span><i style="--swatch: var(--slow-bar)" aria-hidden="true"></i>Slow p95</span>
        </div>
      </div>

      <div class="controls" role="group" aria-label="Endpoint filters and sorting">
        <div class="field">
          <span>Search path</span>
          <ryugi-input id="path-search" aria-label="Search path" type="search" placeholder="e.g. /orders" allowClear></ryugi-input>
        </div>
        <div class="field">
          <span id="method-label">HTTP method</span>
          <ryugi-select id="method" aria-labelledby="method-label" value="all">
            <ryugi-option value="all">All methods</ryugi-option>
            <ryugi-option value="GET">GET</ryugi-option>
            <ryugi-option value="POST">POST</ryugi-option>
            <ryugi-option value="PUT">PUT</ryugi-option>
            <ryugi-option value="PATCH">PATCH</ryugi-option>
            <ryugi-option value="DELETE">DELETE</ryugi-option>
          </ryugi-select>
        </div>
        <div class="field">
          <span id="sort-label">Sort by p95</span>
          <ryugi-select id="sort" aria-labelledby="sort-label" value="desc">
            <ryugi-option value="desc">Highest first</ryugi-option>
            <ryugi-option value="asc">Lowest first</ryugi-option>
          </ryugi-select>
        </div>
        <div class="field">
          <span id="threshold-label">Slow threshold (ms)</span>
          <ryugi-slider-input id="threshold" aria-labelledby="threshold-label" value="450" min="0" max="1200" step="1"></ryugi-slider-input>
        </div>
      </div>

      <div class="table-wrap" role="region" aria-labelledby="endpoints-title" tabindex="0">
        <table aria-labelledby="endpoints-title">
          <colgroup><col class="method-col"><col><col class="number-col"><col class="number-col"><col class="chart-col"><col class="status-col"></colgroup>
          <thead>
            <tr>
              <th scope="col">Method</th>
              <th scope="col">Path</th>
              <th scope="col" class="numeric">p50 (ms)</th>
              <th scope="col" id="p95-heading" class="numeric" aria-sort="descending">p95 (ms)</th>
              <th scope="col"><div class="scale"><span>0</span><span>1,200 ms</span></div><span class="sr-only">Latency chart</span></th>
              <th scope="col">Status</th>
            </tr>
          </thead>
          <tbody id="endpoint-rows"></tbody>
        </table>
      </div>
      <p class="foot">p50 is the median. 95% of requests finish within p95. The vertical marker shows your slow threshold.</p>
    </ryugi-card>
  </main>

  <script>
    const endpoints = [
      ['"'GET', '/v1/health', 8, 22],
      ['POST', '/v1/auth/login', 109, 318],
      ['POST', '/v1/auth/refresh', 46, 121],
      ['GET', '/v1/users/me', 32, 87],
      ['GET', '/v1/users', 94, 284],
      ['GET', '/v1/users/{id}', 41, 116],
      ['PATCH', '/v1/users/{id}', 78, 198],
      ['DELETE', '/v1/users/{id}', 95, 247],
      ['GET', '/v1/products', 112, 336],
      ['GET', '/v1/products/{id}', 53, 138],
      ['GET', '/v1/products/search', 174, 632],
      ['POST', '/v1/products', 139, 382],
      ['PUT', '/v1/products/{id}', 126, 349],
      ['GET', '/v1/orders', 153, 481],
      ['GET', '/v1/orders/{id}', 67, 167],
      ['POST', '/v1/orders', 238, 786],
      ['POST', '/v1/orders/{id}/cancel', 131, 404],
      ['POST', '/v1/payments', 307, 986],
      ['GET', '/v1/payments/{id}', 77, 205],
      ['POST', '/v1/payments/{id}/refund', 265, 873],
      ['GET', '/v1/reports/revenue', 278, 924],
      ['POST', '/v1/reports/export', 224, 711],
      ['POST', '/v1/files', 187, 557],
      ['DELETE', '/v1/files/{id}', 44, 129],
    ];
    const controls = {
      'path-search': 'query',
      method: 'method',
      sort: 'sort',
      threshold: 'threshold',
    };
    const state = { query: '', method: 'all', sort: 'desc', threshold: 450 };
    const methodColors = { GET: 'blue', POST: 'green', PUT: 'purple', PATCH: 'gold', DELETE: 'red' };
    const byId = (id) => document.getElementById(id);
    const formatter = new Intl.NumberFormat('en');
    const maxLatency = 1200;
    const percentage = (value) => (value / maxLatency) * 100 + '%';

    function render() {
      const query = state.query.trim().toLowerCase();
      const descending = state.sort === 'desc';
      const shown = endpoints
        .filter(([method, path]) => (state.method === 'all' || method === state.method) && path.toLowerCase().includes(query))
        .sort((a, b) => descending ? b[3] - a[3] : a[3] - b[3]);
      const slowCount = shown.filter((endpoint) => endpoint[3] > state.threshold).length;
      const highest = shown.length ? shown[descending ? 0 : shown.length - 1][3] : null;

      byId('endpoint-count').textContent = shown.length;
      byId('slow-count').textContent = slowCount;
      byId('slow-detail').textContent = 'p95 above ' + formatter.format(state.threshold) + ' ms';
      byId('highest').textContent = highest === null ? '—' : formatter.format(highest) + ' ms';
      byId('result-count').textContent = shown.length === endpoints.length
        ? 'Showing all ' + endpoints.length + ' endpoints'
        : 'Showing ' + shown.length + ' of ' + endpoints.length + ' endpoints';
      byId('p95-heading').setAttribute('aria-sort', descending ? 'descending' : 'ascending');

      // Row markup uses only the fixed sample data and numeric chart coordinates.
      byId('endpoint-rows').innerHTML = shown.map(([method, path, p50, p95]) => {
        const slow = p95 > state.threshold;
        const marker = Math.min(99.5, (state.threshold / maxLatency) * 100) + '%';
        return "'`
          <tr class="${slow ? '"'slow' : ''}\">
            <td><ryugi-tag color=\""'${methodColors[method]}" size="small" variant="filled">${method}</ryugi-tag></td>
            <th scope="row" class="path-cell"><code>${path}</code></th>
            <td class="numeric">${formatter.format(p50)}</td>
            <td class="numeric p95">${formatter.format(p95)}</td>
            <td aria-hidden="true"><div class="chart">
              <span class="bar bar-50" style="width:${percentage(p50)}"></span>
              <span class="bar bar-95" style="width:${percentage(p95)}"></span>
              <span class="threshold-line" style="left:${marker}"></span>
            </div></td>
            <td>${slow ? '"'<ryugi-tag color=\"orange\" size=\"small\" variant=\"filled\">Slow</ryugi-tag>' : '<span class=\"status-ok\">Within</span>'}</td>
          </tr>"'`;
      }).join('"'') || '<tr><td colspan=\"6\" class=\"empty\">No endpoints match your search and method filter.</td></tr>';
    }

    function updateControl(id, value) {
      if (id === 'threshold') {
        if (value "'!== null && value !== '"'' && Number.isFinite(Number(value))) {
          state.threshold = Math.min(maxLatency, Math.max(0, Number(value)));
        }
      } else if (Object.hasOwn(controls, id)) {
        state[controls[id]] = String(value ?? (id === 'method' ? 'all' : id === 'sort' ? 'desc' : ''));
      }
    }

    document.addEventListener('ryugi-change', (event) => {
      if ("'!Object.hasOwn(controls, event.target.id)) return;
      updateControl(event.target.id, event.detail.value);
      render();
    });

    document.addEventListener('"'ryugi-ui:ready', () => {
      for (const id of Object.keys(controls)) {
        const value = byId(id).value;
        if (value "'!== undefined) updateControl(id, value);
      }
      render();
    }, { once: true });

    render();
  </script>
</body>
</html>
EOF'

